define(["jquery","core/notification"],function($,Notification){"use strict";var SELECTOR='[data-action="local-backupftp-confirm"]';var init=function(){$(document).off("click.localBackupftpConfirmation",SELECTOR).on("click.localBackupftpConfirmation",SELECTOR,function(e){e.preventDefault();var target=$(this);var url=target.attr("href");var message=target.attr("data-confirm-message");if(!url||!message){return}Notification.confirm(M.util.get_string("confirmation","admin"),message,M.util.get_string("yes","moodle"),M.util.get_string("no","moodle"),function(){window.location.assign(url)})})};return{init:init}});